package findings

// Detection describes a deliberately narrow, evidence-backed detector. The
// catalogue is documentation as data: unsupported or derived relationships are
// not silently promoted to vulnerabilities.
type Detection struct {
	ID, Source, Condition, RequiredFields, Severity, Confidence, Remediation string
	Supported                                                                bool
}

func DetectionCatalogue() []Detection {
	return []Detection{
		{ID: "ad.acl.writedacl", Source: "RustHound-CE", Condition: "direct WriteDacl ACE", RequiredFields: "PrincipalSID, ObjectIdentifier, RightName", Severity: "medium/high when sensitive", Confidence: "observed-direct-ace", Remediation: "review principal and remove unnecessary control", Supported: true},
		{ID: "ad.acl.genericall", Source: "RustHound-CE", Condition: "direct GenericAll ACE", RequiredFields: "PrincipalSID, ObjectIdentifier, RightName", Severity: "medium/high when sensitive", Confidence: "observed-direct-ace", Remediation: "review broad object control", Supported: true},
		{ID: "ad.acl.shadow-credentials-potential", Source: "RustHound-CE", Condition: "direct AddKeyCredentialLink ACE", RequiredFields: "PrincipalSID, ObjectIdentifier, RightName", Severity: "medium/high when sensitive", Confidence: "potential-condition", Remediation: "verify account control and key-credential policy", Supported: true},
		{ID: "ad.acl.replication-partial", Source: "RustHound-CE", Condition: "one or more replication rights", RequiredFields: "PrincipalSID, domain ObjectIdentifier, RightName", Severity: "informational until complete", Confidence: "partial-observation", Remediation: "verify the complete replication-right set", Supported: true},
		{ID: "protocol.smb-signing", Source: "NetExec", Condition: "explicit signing-not-required evidence", RequiredFields: "host, signing policy", Severity: "medium", Confidence: "tool-confirmed", Remediation: "require SMB signing", Supported: true},
		{ID: "ad.account.passwd-not-required", Source: "NetExec", Condition: "explicit PASSWD_NOTREQD user-account-control flag", RequiredFields: "account, userAccountControl", Severity: "context-dependent", Confidence: "explicit-uac-flag", Remediation: "review and clear the flag where unnecessary", Supported: true},
		{ID: "ad.account.dont-expire-password", Source: "NetExec", Condition: "explicit DONT_EXPIRE_PASSWORD user-account-control flag", RequiredFields: "account, userAccountControl", Severity: "context-dependent", Confidence: "explicit-uac-flag", Remediation: "review account credential lifecycle and rotation", Supported: true},
		{ID: "ad.domain.weak-minimum-password-length", Source: "NetExec", Condition: "domain default minimum password length below the documented review threshold", RequiredFields: "domain, minPwdLength", Severity: "low/context-dependent", Confidence: "observed-domain-default-policy", Remediation: "review the domain default and any fine-grained policy overrides", Supported: true},
		{ID: "ad.domain.password-expiration-not-enforced", Source: "NetExec", Condition: "domain default maxPwdAge is non-expiring", RequiredFields: "domain, maxPwdAge", Severity: "informational", Confidence: "observed-domain-default-policy", Remediation: "review password policy in context; do not infer account compromise", Supported: true},
		{ID: "ad.domain.machine-account-creation-quota", Source: "NetExec", Condition: "domain ms-DS-MachineAccountQuota is positive", RequiredFields: "domain, ms-DS-MachineAccountQuota", Severity: "informational/context-dependent", Confidence: "observed-domain-default-policy", Remediation: "review directory permissions and whether the quota is required", Supported: true},
		{ID: "protocol.ldap-signing", Source: "NetExec/RelayKing", Condition: "explicit LDAP signing policy evidence", RequiredFields: "host, policy evidence", Severity: "medium", Confidence: "tool-confirmed", Remediation: "require LDAP signing and validate channel binding", Supported: false},
		{ID: "adcs.esc-report", Source: "Certipy", Condition: "explicit ESC identifier in vulnerability output", RequiredFields: "template or CA, ESC identifier, vulnerability text", Severity: "context-dependent", Confidence: "tool-reported-esc", Remediation: "review the reported ESC condition and required prerequisites", Supported: true},
		{ID: "ad.account.pwd-never-expires", Source: "RustHound-CE", Condition: "enabled users with pwdneverexpires, grouped per domain", RequiredFields: "enabled, pwdneverexpires, admincount", Severity: "low; medium when adminCount accounts are included", Confidence: "observed-directory-properties", Remediation: "rotate and remove the flag, or move service accounts to gMSA", Supported: true},
		{ID: "ad.account.reversible-encryption", Source: "RustHound-CE", Condition: "enabled user with encryptedtextpwdallowed", RequiredFields: "enabled, encryptedtextpwdallowed", Severity: "medium", Confidence: "observed-directory-property", Remediation: "clear the flag and reset the password", Supported: true},
		{ID: "ad.account.des-only", Source: "RustHound-CE", Condition: "enabled user with usedeskeyonly", RequiredFields: "enabled, usedeskeyonly", Severity: "low", Confidence: "observed-directory-property", Remediation: "clear the flag and ensure AES keys exist", Supported: true},
		{ID: "ad.account.sid-history", Source: "RustHound-CE", Condition: "user, computer or group with populated sidhistory", RequiredFields: "sidhistory, domainsid", Severity: "medium; high for a same-domain privileged RID", Confidence: "observed-directory-property", Remediation: "remove sIDHistory after migration", Supported: true},
		{ID: "ad.account.password-attribute", Source: "RustHound-CE", Condition: "readable userPassword, unixUserPassword, unicodePwd or msSFU30Password value; value never stored in the Finding", RequiredFields: "userpassword, unixpassword, unicodepassword, sfupassword", Severity: "medium", Confidence: "observed-directory-property", Remediation: "clear the attribute and reset the password", Supported: true},
		{ID: "ad.account.krbtgt-age", Source: "RustHound-CE", Condition: "krbtgt pwdlastset older than 180 days at collection time", RequiredFields: "pwdlastset, collection time", Severity: "low; medium beyond 365 days", Confidence: "observed-directory-property", Remediation: "rotate the krbtgt password twice", Supported: true},
		{ID: "ad.account.privileged-not-protected", Source: "RustHound-CE", Condition: "enabled adminCount user neither sensitive nor a direct Protected Users member", RequiredFields: "admincount, sensitive, Protected Users members", Severity: "low", Confidence: "observed-directory-properties", Remediation: "mark sensitive or add to Protected Users", Supported: true},
		{ID: "ad.account.stale", Source: "RustHound-CE", Condition: "enabled user or computer without lastlogontimestamp in 90 days", RequiredFields: "enabled, lastlogontimestamp, whencreated", Severity: "low", Confidence: "observed-directory-properties", Remediation: "disable or remove unused accounts", Supported: true},
		{ID: "ad.account.laps-not-observed", Source: "RustHound-CE", Condition: "enabled non-DC Windows computer with haslaps=false", RequiredFields: "enabled, isdc, haslaps, operatingsystem", Severity: "medium", Confidence: "observed-directory-properties", Remediation: "deploy Windows LAPS", Supported: true},
		{ID: "ad.domain.functional-level", Source: "RustHound-CE", Condition: "domain functional level; low below 2012 R2", RequiredFields: "functionallevel", Severity: "informational/low", Confidence: "observed-directory-property", Remediation: "raise the functional level", Supported: true},
		{ID: "ad.domain.anonymous-ldap", Source: "RustHound-CE", Condition: "dSHeuristics character 7 equals 2; RustHound-CE reads dSHeuristics from the domain object, where it is normally absent, so this rarely has data", RequiredFields: "dsheuristics", Severity: "medium", Confidence: "observed-directory-property", Remediation: "reset fLDAPBlockAnonOps", Supported: true},
		{ID: "ad.trust.sid-filtering", Source: "RustHound-CE", Condition: "outbound or bidirectional external trust without QUARANTINED_DOMAIN, or forest trust with TREAT_AS_EXTERNAL", RequiredFields: "Trusts TrustAttributes, TrustDirection", Severity: "medium", Confidence: "observed-trust-attributes", Remediation: "enable SID filtering / quarantine", Supported: true},
		{ID: "ad.trust.tgt-delegation", Source: "RustHound-CE", Condition: "trust with CROSS_ORGANIZATION_ENABLE_TGT_DELEGATION", RequiredFields: "Trusts TrustAttributes", Severity: "low", Confidence: "observed-trust-attributes", Remediation: "disable TGT delegation across the trust", Supported: true},
		{ID: "protocol.ldap-signing-netexec-reported", Source: "NetExec", Condition: "LDAP banner reports signing:None; NetExec prints the same value when its probe fails", RequiredFields: "host, banner signing field", Severity: "medium", Confidence: "tool-reported-not-verified", Remediation: "require LDAP signing on domain controllers", Supported: true},
		{ID: "protocol.ldaps-channel-binding-netexec-reported", Source: "NetExec", Condition: "LDAP banner reports channel binding Never (medium) or When Supported (low)", RequiredFields: "host, banner channel-binding field", Severity: "medium/low", Confidence: "tool-reported-not-verified", Remediation: "require LDAPS channel binding", Supported: true},
		{ID: "ad.dns.nonsecure-updates", Source: "NetExec", Condition: "dns-nonsecure lists an AD-integrated zone that allows nonsecure dynamic updates", RequiredFields: "zone, zone scope", Severity: "medium", Confidence: "explicit-module-result", Remediation: "set the zone to secure dynamic updates only", Supported: true},
		{ID: "ad.computer.obsolete-os", Source: "NetExec", Condition: "obsolete lists enabled computers with an unsupported Windows release, grouped per domain", RequiredFields: "dNSHostName, operatingSystem", Severity: "medium", Confidence: "explicit-module-result", Remediation: "upgrade or retire the hosts and remove stale computer accounts", Supported: true},
		{ID: "ad.account.password-attribute-readable", Source: "NetExec", Condition: "get-userPassword or get-unixUserPassword returned an account line for the assessment account; the value is never stored in the Finding", RequiredFields: "account, attribute, reading account", Severity: "high", Confidence: "explicit-module-result", Remediation: "clear the attribute, reset the password, and restrict read access", Supported: true},
		{ID: "relay.explicit-path", Source: "RelayKing", Condition: "explicit classified relay path", RequiredFields: "destination, protocol, impact", Severity: "tool-classified", Confidence: "tool-reported-path", Remediation: "review signing, channel binding and relay destination", Supported: true},
	}
}
